import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;
/** Exact18-column projection of the current readonly Source loader; no schema or SQL writes. */
public final class SourceArmorSqlMethods {
 static final String N="local/lito381/server/NativeArmorProc";
 static void replace(ClassNode c,String old,String next){int count=0;for(var m:c.methods)for(var n:m.instructions)if(n instanceof LdcInsnNode literal&&literal.cst.equals(old)){if(!m.name.equals("load"))throw new AssertionError("only existing startup transaction");literal.cst=next;count++;}if(count!=1)throw new AssertionError("one exact original query "+count);}
 public static void main(String[]a)throws Exception{String old=Files.readString(Path.of(a[3])),next=Files.readString(Path.of(a[4]));try(var base=new JarFile(a[1])){var original=FreezeAcceptedMethods.read(base,N);var c=FreezeAcceptedMethods.read(base,N);replace(c,old,next);byte[] bytes=FreezeAcceptedMethods.bytes(c,false);if(a[0].equals("splice")){var out=Path.of(a[2]).resolve(N+".class");Files.createDirectories(out.getParent());Files.write(out,bytes);}else try(var jar=new JarFile(a[2])){var actual=FreezeAcceptedMethods.read(jar,N);if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(actual,false)))throw new AssertionError("exact query replacement");replace(actual,next,old);if(!Arrays.equals(FreezeAcceptedMethods.bytes(original,false),FreezeAcceptedMethods.bytes(actual,false)))throw new AssertionError("full class inverse");var names=new HashSet<String>();int changed=0;for(var e:Collections.list(base.entries())){names.add(e.getName());var following=jar.getJarEntry(e.getName());if(following==null)throw new AssertionError("removed entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(following).readAllBytes())){if(!e.getName().equals(N+".class"))throw new AssertionError("unrelated archive entry");changed++;}}if(changed!=1||!names.equals(new HashSet<>(Collections.list(jar.entries()).stream().map(JarEntry::getName).toList())))throw new AssertionError("one changed class, no new entries");}}System.out.println("PASS one existing readonly startup SELECT literal; complete archive/class inverse; no schema/numeric/transaction change");}
}
